-- floorfunds-kit: (re)create the database. psql variables: db, role, drop (0/1).
-- KF2: CREATE DATABASE and DROP DATABASE cannot run inside a transaction block or a DO block (PostgreSQL rule), so
-- they cannot share one statement with their check. What the kit does instead:
--   * DROP: a DO block refuses (raises) unless :db is a marked, non-template DB owned by :role (not a superuser); the DROP that follows
--     is generated by a SELECT carrying the same conditions, so it is a no-op if anything changed in between.
--     Remaining window: a concurrent SUPERUSER could swap a different DB in under the same name between the two
--     statements (needs superuser rights, which already allow any DROP).
--   * CREATE: if :db is absent, CREATE DATABASE (fails if someone created it meanwhile). Right after, ONE DO block
--     re-checks it (owner :role and not a superuser, not a template, no comment yet) and COMMENTs it 'floorfunds-kit', REVOKEs PUBLIC
--     CONNECT and GRANTs CONNECT to :role, all in one transaction. If the re-check fails it raises; the unmarked DB
--     is then left in place and every later run refuses it (it has no marker).
--   * existing DB: the same DO block requires the marker, owner :role and not a template, then REVOKE/GRANT.
\if :drop
SELECT set_config('floorfunds_kit.db', :'db', false) AS kit_db, set_config('floorfunds_kit.role', :'role', false) AS kit_role \gset
DO $kit$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_database WHERE datname = current_setting('floorfunds_kit.db') AND NOT datistemplate
                   AND pg_get_userbyid(datdba)::text = current_setting('floorfunds_kit.role')
                   AND NOT (SELECT rolsuper FROM pg_roles WHERE oid = datdba)
                   AND shobj_description(oid, 'pg_database') IS NOT DISTINCT FROM 'floorfunds-kit') THEN
    RAISE EXCEPTION 'floorfunds-kit: refusing to touch a database the kit did not create (no marker, wrong or superuser owner, or a template)';
  END IF;
END
$kit$;
SELECT format('DROP DATABASE %I WITH (FORCE)', :'db') FROM pg_database
 WHERE datname = :'db' AND NOT datistemplate AND pg_get_userbyid(datdba)::text = :'role'
   AND shobj_description(oid, 'pg_database') IS NOT DISTINCT FROM 'floorfunds-kit' \gexec
\endif
SELECT NOT EXISTS (SELECT 1 FROM pg_database WHERE datname = :'db') AS kit_new \gset
\if :kit_new
SELECT format('CREATE DATABASE %I OWNER %I', :'db', :'role') \gexec
\endif
BEGIN;
SELECT set_config('floorfunds_kit.db', :'db', true) AS kit_db, set_config('floorfunds_kit.role', :'role', true) AS kit_role,
       set_config('floorfunds_kit.new', :'kit_new', true) AS kit_new2 \gset
DO $kit$
DECLARE
  db  text := current_setting('floorfunds_kit.db');
  ro  text := current_setting('floorfunds_kit.role');
  new boolean := current_setting('floorfunds_kit.new')::boolean;
  c   text;
BEGIN
  SELECT shobj_description(oid, 'pg_database') INTO c FROM pg_database
   WHERE datname = db AND NOT datistemplate AND pg_get_userbyid(datdba)::text = ro
     AND NOT (SELECT rolsuper FROM pg_roles WHERE oid = datdba);
  IF NOT FOUND OR NOT ((new AND c IS NULL) OR c IS NOT DISTINCT FROM 'floorfunds-kit') THEN
    RAISE EXCEPTION 'floorfunds-kit: refusing to touch a database the kit did not create (no marker, wrong or superuser owner, or a template)';
  END IF;
  IF new THEN EXECUTE format('COMMENT ON DATABASE %I IS %L', db, 'floorfunds-kit'); END IF;
  EXECUTE format('REVOKE CONNECT ON DATABASE %I FROM PUBLIC', db);
  EXECUTE format('GRANT CONNECT ON DATABASE %I TO %I', db, ro);
END
$kit$;
COMMIT;
-- The authorization functions are owned by this role, not by the login database owner.
-- It is not a kit role: no marker, no membership, no password. Preflight does not list it.
SELECT format('CREATE ROLE %I NOLOGIN NOINHERIT NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE NOREPLICATION', :'db' || '_auth_definer')
 WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = :'db' || '_auth_definer') \gexec
